const platform=createPlatform();const NATIVE_PENDING_KEY='indiff.platform.native-pending.v1';let nativeLoadWarning='';
if(platform.native){try{const restored=await platform.loadWorkspace();if(localStorage.getItem(NATIVE_PENDING_KEY)){const cached=localStorage.getItem(STORAGE_KEY),cachedUI=localStorage.getItem(UI_KEY);if(!restored||cached!==serializeState(restored.workspace)||cachedUI!==JSON.stringify(restored.ui))throw Error('이전 기기 저장이 확인되지 않은 복구본이 있습니다. 원본 백업 후 복구본 저장을 선택하세요.');localStorage.removeItem(NATIVE_PENDING_KEY);}if(restored){localStorage.setItem(STORAGE_KEY,serializeState(restored.workspace));localStorage.setItem(UI_KEY,JSON.stringify(restored.ui));}}catch(error){nativeLoadWarning='기기 저장본 보호 중: '+error.message;}}
