const loaded=loadState(makeInitialState());let state=loaded.state,blocked=!!(loaded.warning||nativeLoadWarning),ui=createUI(state.documents),uiWarning='',saveTimer,toastTimer,dialogSubmit,dragTab,selectedNode=null,selectedEdge=null,linkSource=null,activeRun=null,controller=null;
