function toast(t){clearTimeout(toastTimer);$('#toast').textContent=t;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4500);}
const nativeSaves=createPersistenceQueue(platform,status=>{if(!platform.native)return;$('#save-status').textContent=status.state==='saving'?'기기에 저장 중…':status.state==='saved'?'앱 저장소에 저장됨':'기기 저장 실패 · 백업 필요';if(status.state==='saved')localStorage.removeItem(NATIVE_PENDING_KEY);if(status.state==='error')toast(status.error.message);});
function save(){clearTimeout(saveTimer);if(blocked){$('#save-status').textContent='원본 저장 보호 중';return false;}try{validateUI(ui,state.documents,state.workflow.nodes);saveState(state);const raw=JSON.stringify(ui);if(new TextEncoder().encode(raw).length>2*1024*1024)throw Error('레이아웃·메모 한도 2MiB를 초과했습니다.');localStorage.setItem(UI_KEY,raw);$('#save-status').textContent='브라우저에 저장됨';if(platform.native){localStorage.setItem(NATIVE_PENDING_KEY,'1');nativeSaves.enqueue(state,ui);}return true;}catch(e){$('#save-status').textContent='저장 실패 · 백업 필요';toast(e.message);return false;}}
function scheduleSave(){clearTimeout(saveTimer);$('#save-status').textContent=blocked?'원본 저장 보호 중':'저장 중…';saveTimer=setTimeout(save,400);}
const exportFilename=name=>['.indiff.json','.indiff-workflows.json'].includes(name)?name:safeFilename(name);
function download(content,name,type='text/plain;charset=utf-8'){if(platform.native){platform.saveText(exportFilename(name),content,/^indiff-ui-workspace-/.test(name)?'workspace':'text').then(result=>{if(!result.canceled)toast('선택한 위치에 저장했습니다.');}).catch(error=>toast(error.message));return;}const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=exportFilename(name);document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function field(name,label,value='',type='input',extra=''){return `<label class="field">${esc(label)}<${type} name="${name}" ${extra}>${type==='textarea'?esc(value):''}</${type}>${type==='input'?'':''}</label>`.replace(`<input name="${name}" ${extra}>`,`<input name="${name}" value="${esc(value)}" ${extra}>`).replace('</input>','');}
function selectField(name,label,entries,value){return `<label class="field">${esc(label)}<select name="${name}">${entries.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
function openDialog(title,fields,onSave){$('#dialog-title').textContent=title;$('#dialog-fields').innerHTML=fields;$('#dialog-error').textContent='';dialogSubmit=onSave;$('#edit-dialog').showModal();setTimeout(()=>$('#dialog-fields input, #dialog-fields textarea, #dialog-fields select')?.focus(),0);}
$('#edit-form').onsubmit=e=>{e.preventDefault();try{dialogSubmit(new FormData(e.target));$('#edit-dialog').close();save();render();}catch(err){$('#dialog-error').textContent=err.message;}};
$('#dialog-close').onclick=$('#dialog-cancel').onclick=()=>$('#edit-dialog').close();
function open(id,{pane=activePane(),pinned=false}={}){openTab(pane,id,pinned||id.startsWith('@'));ui.activePane=pane.id;if(docById(id))state.activeDocumentId=id;linkSource=null;save();render();if(matchMedia('(max-width:760px)').matches)document.body.classList.remove('mobile-tree-open');}
function setActive(id){if(ui.activePane===id)return;ui.activePane=id;$$('.pane').forEach(el=>el.classList.toggle('active',el.dataset.pane===id));renderMobile();updateStatus();scheduleSave();}
function updateStatus(){const id=activePane().active;$('#status-path').textContent=id?(ui.paths[id]||virtualNames[id]||id):'빈 패널';$('#indi-run-status').textContent=activeRun?`규칙 기반 로컬 실행 · ${activeRun.steps.filter(s=>s.status==='completed').length}/${activeRun.steps.length} 완료`:'진행 중인 로컬 실행 없음';}
function renderTree(){const files=state.documents;const root={dirs:new Map(),docs:[]};for(const d of files){const parts=(ui.paths[d.id]||`Documents/${d.title}.md`).split('/');let branch=root;for(const part of parts.slice(0,-1)){if(!branch.dirs.has(part))branch.dirs.set(part,{dirs:new Map(),docs:[]});branch=branch.dirs.get(part);}branch.docs.push([d,parts.at(-1)]);}const renderBranch=b=>[...b.dirs.entries()].map(([name,child])=>`<details open><summary><span class="caret">›</span><span class="file-icon">▱</span><span>${esc(name)}</span></summary><div class="tree-children">${renderBranch(child)}</div></details>`).join('')+b.docs.map(([d,name])=>`<button class="tree-item ${activePane().active===d.id?'active':''}" data-open="${esc(d.id)}" title="${esc(ui.paths[d.id])} · 우클릭: 이름 변경"><span class="file-icon">▤</span><span class="name">${esc(name)}</span></button>`).join('');$('#file-tree').innerHTML=`<details open class="project-root"><summary><span class="caret">›</span><span class="file-icon">▱</span><b>INDIFF Workspace</b></summary><div class="tree-children">${renderBranch(root)||'<div class="tree-empty">검색 결과 없음</div>'}</div></details><div class="tree-section">WORKSPACE</div>${Object.entries(virtualNames).map(([id,name])=>`<button class="tree-item ${activePane().active===id?'active':''}" data-open="${id}"><span class="file-icon">${{'@team':'◌','@board':'⌘','@runs':'◷','@about':'ⓘ'}[id]}</span><span class="name">${name}</span>${id==='@team'?'<small>로컬</small>':''}</button>`).join('')}`;}
$('#file-tree').onclick=e=>{const b=e.target.closest('[data-open]');if(b)open(b.dataset.open);};
$('#file-tree').ondblclick=e=>{const b=e.target.closest('[data-open]');if(b)open(b.dataset.open,{pinned:true});};
