function renderSearch(){const q=$('#file-search').value.toLocaleLowerCase(),docs=state.documents.filter(d=>`${ui.paths[d.id]}\n${d.body}\n${d.notes.map(n=>n.text).join('\n')}`.toLocaleLowerCase().includes(q));$('#search-results').innerHTML=docs.map(d=>`<button class="search-result" data-search-open="${esc(d.id)}"><b>${esc(d.title)}</b><small>${esc(ui.paths[d.id])}</small></button>`).join('')||'<p class="hint">검색 결과가 없습니다.</p>';}
