function findSplit(node,id){if(node.id===id)return node;if(node.type==='split')return findSplit(node.children[0],id)||findSplit(node.children[1],id);}
function trackPointer(el,e,onMove,onEnd){const pointer=e.pointerId;el.setPointerCapture(pointer);document.body.classList.add('dragging');const move=ev=>{if(ev.pointerId===pointer)onMove(ev);},end=ev=>{if(ev.pointerId!==pointer)return;el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);el.removeEventListener('pointercancel',end);document.body.classList.remove('dragging');onEnd?.();};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);}
function bindPointerActions(){$$('[data-resize]').forEach(div=>{div.onpointerdown=e=>{e.preventDefault();const split=findSplit(ui.layout,div.dataset.resize),box=div.parentElement.getBoundingClientRect();trackPointer(div,e,ev=>{split.ratio=clamp(split.axis==='row'?(ev.clientX-box.left)/box.width:(ev.clientY-box.top)/box.height,.15,.85);div.previousElementSibling.style.flexBasis=`calc(${split.ratio*100}% - 1px)`;},save);};div.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const split=findSplit(ui.layout,div.dataset.resize);split.ratio=clamp(split.ratio+(['ArrowRight','ArrowDown'].includes(e.key)?.05:-.05),.15,.85);save();render();};});$$('.bd-stage').forEach(stage=>{stage.onpointerdown=e=>{if(e.button!==0||e.target.closest('button,.bd-edge,.bd-tools,.bd-runbar,.bd-selection'))return;const card=e.target.closest('[data-node]'),start={x:e.clientX,y:e.clientY},cam={...ui.camera};if(card){e.preventDefault();const id=card.dataset.node,index=state.workflow.nodes.findIndex(n=>n.id===id),pos={...positionOf(state.workflow.nodes[index],index)};selectedNode=id;selectedEdge=null;$$('.bd-card').forEach(c=>c.classList.toggle('selected',c.dataset.node===id));trackPointer(card,e,ev=>{ui.positions[id]={x:clamp(pos.x+(ev.clientX-start.x)/ui.camera.zoom,-9000,9000),y:clamp(pos.y+(ev.clientY-start.y)/ui.camera.zoom,-9000,9000)};$$(`[data-node="${cssId(id)}"]`).forEach(c=>{c.style.left=`${ui.positions[id].x}px`;c.style.top=`${ui.positions[id].y}px`;});$$('.bd-edges>g').forEach(g=>g.innerHTML=renderEdges());},()=>{save();render();});}else{selectedNode=null;selectedEdge=null;e.preventDefault();trackPointer(stage,e,ev=>{ui.camera.x=clamp(cam.x+ev.clientX-start.x,-9000,9000);ui.camera.y=clamp(cam.y+ev.clientY-start.y,-9000,9000);updateBoardTransforms();},()=>{save();render();});}};stage.onwheel=e=>{e.preventDefault();if(e.ctrlKey||e.metaKey)zoomBoard(e.deltaY<0?1.08:1/1.08);else{ui.camera.x=clamp(ui.camera.x-e.deltaX,-9000,9000);ui.camera.y=clamp(ui.camera.y-e.deltaY,-9000,9000);updateBoardTransforms();scheduleSave();}};stage.addEventListener('click',e=>{const edge=e.target.closest('[data-edge]');if(edge){selectedEdge=edge.dataset.edge;selectedNode=null;render();}});stage.onkeydown=e=>{if(e.target.closest('button,input,textarea'))return;const card=e.target.closest('[data-node]');if(card&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const id=card.dataset.node,index=state.workflow.nodes.findIndex(n=>n.id===id),pos={...positionOf(state.workflow.nodes[index],index)},step=e.shiftKey?30:10;pos.x+=e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0;pos.y+=e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0;ui.positions[id]={x:clamp(pos.x,-9000,9000),y:clamp(pos.y,-9000,9000)};selectedNode=id;save();render();$(`[data-node="${cssId(id)}"]`)?.focus();}else if(['Delete','Backspace'].includes(e.key)&&selectedEdge){e.preventDefault();deleteEdge();}else if(e.key==='Escape'){linkSource=null;selectedEdge=null;render();}};});}
async function startRun(){if(activeRun)return;if(blocked)return toast('저장 원본 보호를 해제하거나 백업을 복원한 뒤 실행하세요.');if(state.documents.length>30||state.documents.reduce((n,d)=>n+d.title.length+d.body.length,0)>16000)return toast('로컬 규칙 실행은 문서 30개, 제목·본문 합계 16,000자까지입니다.');const workflow=structuredClone(state.workflow),documents=structuredClone(state.documents);controller=new AbortController();activeRun={steps:workflow.nodes.map(n=>({nodeId:n.id,status:'pending'}))};render();try{const result=await executeWorkflow(workflow,{documents,signal:controller.signal,delayMs:350,onStep:(_step,run)=>{activeRun=run;render();}});const candidate={...state,runs:[{...result,workflowTitle:workflow.title},...state.runs].slice(0,30)};while(candidate.runs.length>1){try{serializeState(candidate);break;}catch{candidate.runs.pop();}}serializeState(candidate);state=candidate;save();toast(result.status==='completed'?'로컬 규칙 실행 완료 · 실행 기록에 저장했습니다.':`로컬 실행 ${statuses[result.status]||result.status}`);}catch(e){toast(`로컬 실행 오류: ${e.message}`);}finally{activeRun=null;controller=null;render();}}
function renderRuns(){return `<section class="runs-page"><div class="runs-inner"><h1>실행 기록</h1><p style="color:var(--muted-fg);font-size:12px">규칙 기반 로컬 처리 결과입니다. AI 생성·외부 도구·미디어 렌더링은 실행하지 않습니다.</p>${state.runs.length?state.runs.map((r,i)=>`<details class="run-item" ${i===0?'open':''}><summary><span>${esc(statuses[r.status]||r.status)} · ${esc(r.workflowTitle||'로컬 실행')}</span><small>${new Date(r.startedAt).toLocaleString('ko-KR')}</small></summary><p style="font-size:11px;color:var(--muted-fg)">${r.steps.map(s=>`${esc(s.title||s.nodeId)}: ${esc(statuses[s.status])}`).join('<br>')}</p><pre>${esc(r.output||r.errors?.join('\n')||'출력 없음')}</pre><button data-action="save-run" data-id="${esc(r.id)}" ${!r.output?'disabled':''}>결과를 문서로</button> <button data-action="export-run" data-id="${esc(r.id)}">기록 JSON ↓</button></details>`).join(''):'<p style="color:var(--muted-fg)">보드에서 로컬 규칙 실행을 시작하면 여기에 기록됩니다.</p>'}</div></section>`;}
function saveRun(id){const run=state.runs.find(r=>r.id===id);if(!run?.output)return;if(state.documents.length>=200)return toast('문서 한도 200개에 도달했습니다.');const d={id:uid('doc'),title:`로컬 실행 결과 ${state.runs.indexOf(run)+1}`,body:'# 로컬 규칙 실행 결과\n\nAI 생성물이 아닌 로컬 텍스트 처리 결과입니다.\n\n'+run.output,tags:['실행 결과'],updatedAt:new Date().toISOString(),notes:[]};state.documents.push(d);ui.paths[d.id]=uniquePath(`Results/${d.title}.md`);open(d.id,{pinned:true});}
function renderAbout(){return `<section class="about-page"><div class="about-inner"><h1>INDIFF · UI 교정 작업본</h1><p>원본의 어두운 zinc 색상, Project 파일 트리, 32px 탭, 분할 패널과 26px 상태바를 기준으로 교정하는 독립 로컬 구현입니다. 이 단계는 Windows EXE·Android APK 제작 완료나 원본 앱의 전체 기능 완성을 뜻하지 않습니다.</p><h2>이 작업본에서 동작하는 것</h2><ul><li>문서 경로별 파일 트리, 내용 검색, 새 문서·TXT/Markdown 가져오기·이름 변경·읽기·편집·메모·내보내기</li><li>한 번 클릭은 임시 보기 탭, 두 번 클릭 또는 편집은 고정 탭. 탭 닫기·재정렬·다른 패널로 이동</li><li>좌우·상하 분할 최대 4개와 크기 조절. 모바일에서는 같은 패널을 하단 선택으로 오갑니다.</li><li>자유 배치 보드, 곡선 연결선, 입력/출력 점 연결, 순환 거부, 연결 삭제, 확대·축소·이동</li><li>역할·지시 저장과 대화 형태의 나의 메모. 상대방·AI 응답은 생성하지 않습니다.</li><li>통계·핵심어·원문 기반 구성·입력 검사의 로컬 규칙 실행, 중단·기록·결과 저장</li></ul><h2>아직 연결되지 않은 플랫폼 기능</h2><ul><li>Claude/Codex/AI 모델·터미널·OS 명령·에이전트 실행·MCP 연결</li><li>실제 디스크 폴더 감시·임의 파일 편집·서버 프로젝트 관리·동시 협업·기기 간 동기화</li><li>PDF/HWPX/XLSX/슬라이드/미디어 편집기·브라우저 임베드·스크린샷 도구</li><li>Electron/Windows EXE·Android APK·네이티브 권한과 설치·서명·업데이트</li></ul><h2>기기 호스트 구현</h2><p>${platform.native?'네이티브 브리지가 감지됐습니다. 문서·팀 메모·DAG·탭·분할 상태를 앱 전용 저장소에 순차 저장하며, OS 파일 선택 화면으로 텍스트와 백업을 가져오고 저장합니다.':'브라우저 실행입니다. Android SAF/AtomicFile 및 Windows Electron IPC 소스가 추가됐지만 이 웹 화면은 설치 앱이 아닙니다.'} Windows 호스트 페어링·동기화, AI·CLI는 미연결입니다. APK/EXE의 실제 빌드·설치 검증은 아직 완료되지 않았습니다.</p><h2>저장과 백업</h2><p>브라우저 실행 시 문서와 상태는 현재 origin의 localStorage에 저장됩니다. 네이티브 호스트에서는 앱 전용 원자 저장도 수행합니다. 사이트 주소·포트 변경, 브라우저 초기화 또는 시크릿 모드 종료 시 이어지지 않을 수 있습니다. 작업공간 백업에는 문서·역할·업무·기록뿐 아니라 탭·분할·보드 위치·로컬 대화 메모가 들어갑니다. 복원은 현재 작업을 대체하므로 확인 후 진행합니다.</p><div class="about-actions"><button data-action="export-backup">작업공간 백업 ↓</button><button data-action="import-backup">백업 복원</button><button data-action="clear-chat">로컬 대화 메모 정리</button>${platform.native?'':'<a href="./INDIFF_WindowsAndroid_Source_Incomplete.zip" download>전체 소스 ZIP ↓</a>'}</div><h2>로컬 실행</h2><div class="commands">Node.js 20 이상\nnpm start\nhttp://127.0.0.1:4173\n\nnpm run check\nnpm test\nnpm run build</div><p>추가 설치나 API 키가 필요하지 않습니다. 원본 server.js·추출 코드·별도 라이선스 자산은 포함하거나 실행하지 않습니다. Pretendard는 시스템에 설치된 경우에만 사용하며 미설치 시 시스템 고딕을 사용합니다.</p><h2>원본과의 차이와 권리</h2><p>원본 UI 구조는 정적 텍스트 관찰을 참고했고 이 코드와 아이콘·CSS 구슬은 새로 작성했습니다. 원본의 서버/클라이언트 실행 코드, 이미지, 폰트, 상표 로고는 배포물에 복사하지 않았습니다. 원본 소스 재사용·브랜딩·상용 배포 권리는 별도 검토가 필요합니다. 현재 작업본은 비공개 검수 단계이며 플랫폼 앱 완성본이 아닙니다.</p></div></section>`;}
function exportBackup(){try{const workspace=parseState(serializeState(state));validateUI(ui,state.documents,state.workflow.nodes);const json=JSON.stringify({format:UI_FORMAT,version:1,workspace,ui},null,2);if(new TextEncoder().encode(json).length>MAX_BACKUP_BYTES+2*1024*1024)throw Error('전체 백업 한도 7MiB를 초과했습니다.');download(json,`indiff-ui-workspace-${new Date().toISOString().slice(0,10)}.json`,'application/json');toast('작업공간과 UI 상태를 백업했습니다.');}catch(e){toast(e.message);}}
$('#export-backup').onclick=exportBackup;$('#import-backup').onclick=pickBackupFile;
$('#backup-import').onchange=async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(activeRun)throw Error('로컬 실행을 마치거나 중단한 뒤 복원하세요.');if(file.size>MAX_BACKUP_BYTES+2*1024*1024)throw Error('백업 한도는 7MiB입니다.');const raw=(await file.text()).replace(/^\uFEFF/,''),parsed=JSON.parse(raw);let nextState,nextUI;if(parsed.format===UI_FORMAT&&parsed.version===1){nextState=parseState(JSON.stringify(parsed.workspace));nextUI=validateUI(parsed.ui,nextState.documents,nextState.workflow.nodes);}else if(parsed.format==='indiff.platform-workspace'&&parsed.version===1){const restored=parseSnapshot(parsed);nextState=restored.workspace;nextUI=restored.ui;}else{nextState=parseState(raw);nextUI=createUI(nextState.documents);}if(activeRun)throw Error('실행 중에는 복원할 수 없습니다.');if(!confirm('현재 문서·탭·보드·메모를 백업 내용으로 대체할까요? 현재 작업이 필요하면 먼저 백업하세요.'))return;saveState(nextState);localStorage.setItem(UI_KEY,JSON.stringify(nextUI));state=nextState;ui=nextUI;blocked=false;selectedNode=null;selectedEdge=null;linkSource=null;$('#recovery-bar')?.remove();save();render();toast('백업을 복원했습니다.');}catch(e){toast(e.message);}};
$('#text-import').onchange=async e=>{const files=[...(e.target.files||[])];e.target.value='';if(blocked)return toast('기존 저장 원본 보호를 먼저 해제하거나 백업을 복원하세요.');let n=0,errors=[];for(const file of files){try{if(file.size>1024*1024)throw Error('가져오기 파일 한도는 1MiB입니다.');if(state.documents.length>=200)throw Error('문서 한도 200개');const kind=originalFileKind(file.name);if(kind==='yaml-unsupported')throw Error('원본 YAML은 아직 지원하지 않습니다. 원본에서 workflow.json으로 내보내세요.');let content,tags=['가져옴'];if(kind==='workflow'){const original=parseOriginalWorkflow(await file.text());content={title:original.name||file.name,body:serializeOriginalWorkflow(original)};tags=['원본 workflow JSON'];}else if(['project-registry','workflow-view-state'].includes(kind)){parseOriginalProjectState(await file.text(),file.name);content={title:file.name,body:await file.text()};tags=['원본 상태 · 보존 전용'];}else content=await importTextFile(file);const d={...content,id:uid('doc'),tags,updatedAt:new Date().toISOString(),notes:[]};const candidate={...state,documents:[...state.documents,d],activeDocumentId:d.id};serializeState(candidate);state=candidate;ui.paths[d.id]=uniquePath(`${kind==='workflow'?'workflows':kind==='unsupported'?'Documents':'OriginalState'}/${file.name.replaceAll('/','-')}`);if(!/\.(md|markdown|txt|json)$/i.test(ui.paths[d.id]))ui.paths[d.id]+='.md';openTab(activePane(),d.id,true);n++;}catch(e){errors.push(`${file.name}: ${e.message}`);}}save();render();toast(`${n}개 가져옴${errors.length?' · '+errors.join(' / '):''}`);};
function toggleSidebar(){if(matchMedia('(max-width:760px)').matches)document.body.classList.toggle('mobile-tree-open');else document.body.classList.toggle('sidebar-off');}
$('.sidebar-toggle').innerHTML=svg('panel');$('.sidebar-toggle').onclick=toggleSidebar;$('#sidebar-rail').innerHTML=svg('panel');$('#sidebar-rail').onclick=toggleSidebar;$('#focus-search').innerHTML=svg('search');$('#focus-search').onclick=showSearch;$('#open-about').innerHTML=svg('info');$('#open-about').onclick=$('#status-about').onclick=()=>open('@about');$('#new-file').innerHTML=svg('file');$('#new-file').onclick=()=>newDocument();$('#import-file').innerHTML=svg('upload');$('#import-file').onclick=pickTextFile;$('#indi-orb').onclick=()=>{$('#indi-card').hidden=!$('#indi-card').hidden;$('#indi-orb').classList.toggle('open',!$('#indi-card').hidden);};$('#close-indi').onclick=()=>{$('#indi-card').hidden=true;$('#indi-orb').classList.remove('open');};$('#indi-open-board').onclick=()=>{$('#indi-card').hidden=true;open('@board');};
$('#sidebar-resize').onpointerdown=e=>{e.preventDefault();trackPointer(e.currentTarget,e,ev=>document.documentElement.style.setProperty('--lnb-w',`${clamp(ev.clientX,180,450)}px`));};$('#sidebar-resize').onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const current=$('.lnb').getBoundingClientRect().width;document.documentElement.style.setProperty('--lnb-w',`${clamp(current+(e.key==='ArrowRight'?10:-10),180,450)}px`);}};
document.addEventListener('pointerdown',e=>{if(matchMedia('(max-width:760px)').matches&&document.body.classList.contains('mobile-tree-open')&&!e.target.closest('.lnb,#sidebar-rail'))document.body.classList.remove('mobile-tree-open');});
window.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='b'){e.preventDefault();toggleSidebar();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();if(save())toast(platform.native?'기기 저장 요청을 보냈습니다. 저장 표시를 확인하세요.':'브라우저에 저장했습니다.');}if(e.key==='Escape'){document.body.classList.remove('mobile-tree-open');$('#indi-card').hidden=true;if(linkSource){linkSource=null;render();}}});
window.addEventListener('pagehide',()=>{save();controller?.abort();});
window.addEventListener('indiff-native-pause',save);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')save();});
function nativeFile(result){const bytes=new TextEncoder().encode(result.text);return {name:result.name,size:bytes.length,text:async()=>result.text,arrayBuffer:async()=>bytes.buffer};}
async function pickTextFile(){if(!platform.native)return $('#text-import').click();try{const result=await platform.pickFile('text');if(!result.canceled)await $('#text-import').onchange({target:{files:[nativeFile(result)],value:''}});}catch(error){toast(error.message);}}
async function pickBackupFile(){if(!platform.native)return $('#backup-import').click();try{const result=await platform.pickFile('workspace');if(!result.canceled)await $('#backup-import').onchange({target:{files:[nativeFile(result)],value:''}});}catch(error){toast(error.message);}}
render();if(blocked){const bar=document.createElement('div');bar.id='recovery-bar';bar.className='recovery-banner';bar.innerHTML='저장 데이터를 읽지 못해 원본을 보호합니다. 자동 저장하지 않습니다.<button id="raw-backup">원본 백업</button><button id="reset-local">예제로 초기화</button>';document.body.append(bar);if(nativeLoadWarning&&!loaded.warning&&!uiWarning){const recover=document.createElement('button');recover.textContent='이 화면의 복구본을 기기에 저장';recover.onclick=()=>{if(!confirm('이 화면의 문서·탭·보드 복구본으로 앱 저장소를 대체할까요? 먼저 원본 백업을 권장합니다.'))return;blocked=false;bar.remove();save();};bar.append(recover);}$('#raw-backup').onclick=()=>download(JSON.stringify({workspace:localStorage.getItem(STORAGE_KEY),layout:localStorage.getItem(UI_KEY)},null,2),'indiff-protected-storage.json','application/json');$('#reset-local').onclick=()=>{if(!confirm('보호 중인 저장 데이터를 현재 예제로 대체할까요? 필요하면 먼저 원본을 백업하세요.'))return;state=makeInitialState();ui=createUI(state.documents);blocked=false;bar.remove();save();render();};$('#save-status').textContent='원본 저장 보호 중';toast(nativeLoadWarning||loaded.warning||uiWarning);}else save();

// Original-file inspector keeps original cards/links/metadata, independently of demo DAG.
function renderOriginalWorkflow(document){try{const original=parseOriginalWorkflow(document.body),view=inspectOriginalWorkflow(original);return `<section class="original-workflow"><h1>${esc(view.name)}</h1><p class="hint">원본 cards·links JSON · ${view.nodes.length}개 카드 / ${view.edges.length}개 연결 · 실행 미연결</p><p class="hint">원본 파일 구조를 보존합니다. 편집은 이 작업공간 사본에 적용하며, 원본 파일에 덮어쓰지 않습니다.</p>${view.warnings.map(w=>`<p class="hint">${esc(w)}</p>`).join('')}<div class="original-cards">${view.nodes.map(node=>`<article class="original-card"><header><b>${esc(node.title)}</b><small>${esc(node.kind)} · 미연결</small></header><p>${esc(node.does)}</p><dl><dt>ID</dt><dd>${esc(node.id)}</dd><dt>폴더 참조</dt><dd>${esc(node.folder)}</dd><dt>위치</dt><dd>${esc(node.position?.join(', ')||'미지정')}</dd></dl><button data-original-card="${esc(node.id)}" data-id="${esc(document.id)}">카드 편집</button><button data-original-position="${esc(node.id)}" data-id="${esc(document.id)}">위치 편집</button></article>`).join('')}</div><h2>원본 연결</h2><ul>${view.edges.map(edge=>`<li>${esc(edge.from)}${edge.port?':'+esc(edge.port):''} → ${esc(edge.to)}${edge.label?' · '+esc(edge.label):''}</li>`).join('')}</ul><p class="hint">AI·shell·http·파일·trigger 종류를 보존만 합니다. 원본 실행으로 연결하거나 로컬 규칙으로 바꾸지 않습니다. 전체 JSON은 편집 탭에서 확인하고 ↓로 별도 저장할 수 있습니다.</p></section>`;}catch(error){return `<p class="hint">${esc(error.message)} 원문은 보존됩니다. 편집 탭에서 JSON을 확인하세요.</p>`;}}
function editOriginalCard(document,id){const original=parseOriginalWorkflow(document.body),card=original.cards.find(c=>c.id===id);if(!card)throw Error('원본 카드를 찾을 수 없습니다.');openDialog('원본 카드 · 사본 편집',field('title','카드 이름',card.title||'')+field('does','하는 일',card.does??card.role??'','textarea')+field('prompt','지시',card.prompt||'','textarea')+field('format','출력 형식',card.format||'','textarea')+selectField('mode','실행 모드 메타데이터 (실행 안 함)',[['','원본 기본'],['plan','plan'],['auto','auto']],card.mode||''),form=>{document.body=serializeOriginalWorkflow(updateOriginalCard(original,id,{title:String(form.get('title')),does:String(form.get('does')),prompt:String(form.get('prompt')),format:String(form.get('format')),mode:String(form.get('mode'))}));document.updatedAt=new Date().toISOString();});}
function editOriginalPosition(document,id){const original=parseOriginalWorkflow(document.body),position=original.layout?.[id]||[60,80];openDialog('원본 카드 위치 · 사본 편집',field('x','X',position[0],'input','type="number"')+field('y','Y',position[1],'input','type="number"'),form=>{document.body=serializeOriginalWorkflow(updateOriginalPosition(original,id,[Number(form.get('x')),Number(form.get('y'))]));document.updatedAt=new Date().toISOString();});}
